import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), k = (int) nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        // The k-1 largest packets get their own channels; the rest share one channel.
        int remaining = n - k + 1, j = remaining / 2;
        long middle = remaining % 2 == 1 ? 2 * a[j] : a[j - 1] + a[j]; // twice the median
        long total = 0;
        for (int i = remaining; i < n; i++) total += a[i];
        System.out.println(total + (middle + 1) / 2);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	slices.Sort(a)
	// The k-1 largest packets get their own channels; the rest share one channel.
	remaining := n - k + 1
	j := remaining / 2
	middle := 2 * a[j] // twice the median
	if remaining%2 == 0 {
		middle = a[j-1] + a[j]
	}
	total := int64(0)
	for i := remaining; i < n; i++ {
		total += a[i]
	}
	fmt.Println(total + (middle+1)/2)
}
